    }

    @Override
    protected BigDecimal diarias(Estadia estadia) {
        return PRECO_FECHADO.get(estadia.quarto().tipo());
    }

    @Override
    public BigDecimal devolucao(BigDecimal valorPago) {
        return Dinheiro.percentual(valorPago, 50);
    }
